import React from 'react';

import { getDiffDate } from '@helpers/dateHelper';
import { formatAltitude } from '@helpers/formatHelper';
import { getDistanceBetweenPointsInMeters } from '@helpers/gpsHelper';
import { round } from '@helpers/mathHelper';

import { formatDistance } from '../../../@classes/XneekPolylineEditor/helpers';
import { IBaseRouteObjectPoint } from '../../../@types/routes.types';

interface IElevationChartProps {
  points: Array<[number, number, number]>;
  timestamps?: number[]; // Array of timestamps in milliseconds
  onStartCursorMove?: (e: MouseEvent) => void;
  onEndCursorMove?: (e: MouseEvent) => void;
  onCursorMove?: (
    p: [number, number, number],
    distance: number,
    time: number,
    e: MouseEvent,
  ) => void;
  valueFormater?: (x: number) => string;
  timeFormatter?: (timestamp: number) => string; // Custom time formatter
  poi?: IBaseRouteObjectPoint[];
  padding?: {
    top?: number;
    right?: number;
    bottom?: number;
    left?: number;
  };
  ref?: React.RefObject<SVGSVGElement | null>;

  // пропсы для планового графика (план.факт)
  secondaryPoints?: Array<[number, number, number]>;
  secondaryOptions?: {
    color?: string;
    strokeDasharray?: string;
    strokeWidth?: number;
  };
}

const defaultPadding = {
  top: 20,
  right: 20,
  bottom: 30,
  left: 40,
};

// Default time formatter
const defaultTimeFormatter = (timestamp: number): string => {
  const date = new Date(timestamp);
  return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}:${date.getSeconds().toString().padStart(2, '0')}`;
};

// Format duration in milliseconds to readable time
const formatDuration = (ms: number): string => {
  return getDiffDate(new Date(0), new Date(ms)).toLocaleTimeString();
};

const ElevationChart: React.FC<IElevationChartProps> = ({
  points,
  timestamps,
  onStartCursorMove,
  onEndCursorMove,
  onCursorMove,
  padding: paddingProps,
  valueFormater = formatAltitude,
  timeFormatter = defaultTimeFormatter,
  poi,
  ref,
  secondaryPoints,
  secondaryOptions = {},
}) => {
  const svgRef = ref ?? React.useRef<SVGSVGElement>(null);
  const timeGroupRef = React.useRef<SVGGElement>(null);
  const poiGroupRef = React.useRef<SVGGElement>(null);
  const polylineRef = React.useRef<SVGPolylineElement>(null);
  const secondaryPolylineRef = React.useRef<SVGPolylineElement>(null);
  const cursorLineRef = React.useRef<SVGLineElement>(null);
  const cursorLineHorizontalRef = React.useRef<SVGLineElement>(null);
  const cursorTextRef = React.useRef<SVGTextElement>(null);
  const elevationLinesRef = React.useRef<SVGGElement>(null);
  const yAxisLabelsRef = React.useRef<SVGGElement>(null);

  const padding = { ...defaultPadding, ...paddingProps };

  // Function to find interpolated point at a specific time
  const getInterpolatedPointAtTime = (
    targetTime: number,
    pPoints: Array<[number, number, number]>,
    pointTimeMap: number[],
  ) => {
    if (pPoints.length === 0 || !timestamps) return null;
    if (targetTime <= pointTimeMap[0]) return pPoints[0];
    if (targetTime >= pointTimeMap[pointTimeMap.length - 1]) return pPoints[pPoints.length - 1];

    // Find the segment where the time falls
    let segmentIndex = 0;
    while (segmentIndex < pointTimeMap.length - 1 && targetTime > pointTimeMap[segmentIndex + 1]) {
      segmentIndex++;
    }

    if (segmentIndex >= pPoints.length - 1) return pPoints[pPoints.length - 1];

    const startPoint = pPoints[segmentIndex];
    const endPoint = pPoints[segmentIndex + 1];
    const segmentStartTime = pointTimeMap[segmentIndex];
    const segmentEndTime = pointTimeMap[segmentIndex + 1];
    const segmentDuration = segmentEndTime - segmentStartTime;

    if (segmentDuration <= 0) return startPoint;

    const ratio = (targetTime - segmentStartTime) / segmentDuration;

    // Linear interpolation for all components (lon, lat, elevation)
    const interpolatedPoint: [number, number, number] = [
      startPoint[0] + (endPoint[0] - startPoint[0]) * ratio,
      startPoint[1] + (endPoint[1] - startPoint[1]) * ratio,
      startPoint[2] + (endPoint[2] - startPoint[2]) * ratio,
    ];

    return interpolatedPoint;
  };

  // Helper function for distance-based interpolation (keep original)
  const getInterpolatedPointAtDistance = (
    distance: number,
    pPoints: Array<[number, number, number]>,
    pointDistanceMap: number[],
  ) => {
    if (pPoints.length === 0) return null;
    if (distance <= 0) return pPoints[0];
    if (distance >= pointDistanceMap[pointDistanceMap.length - 1])
      return pPoints[pPoints.length - 1];

    let segmentIndex = 0;
    while (
      segmentIndex < pointDistanceMap.length - 1 &&
      distance > pointDistanceMap[segmentIndex + 1]
    ) {
      segmentIndex++;
    }

    if (segmentIndex >= pPoints.length - 1) return pPoints[pPoints.length - 1];

    const startPoint = pPoints[segmentIndex];
    const endPoint = pPoints[segmentIndex + 1];
    const segmentStartDistance = pointDistanceMap[segmentIndex];
    const segmentEndDistance = pointDistanceMap[segmentIndex + 1];
    const segmentLength = segmentEndDistance - segmentStartDistance;

    if (segmentLength <= 0) return startPoint;

    const ratio = (distance - segmentStartDistance) / segmentLength;

    const interpolatedPoint: [number, number, number] = [
      startPoint[0] + (endPoint[0] - startPoint[0]) * ratio,
      startPoint[1] + (endPoint[1] - startPoint[1]) * ratio,
      startPoint[2] + (endPoint[2] - startPoint[2]) * ratio,
    ];

    return interpolatedPoint;
  };

  // Получение плановой высоты по расстоянию (интерполяция по secondaryPoints)
  const getPlannedElevationAtDistance = (
    distance: number,
    secPoints: Array<[number, number, number]>,
    secDistanceMap: number[],
  ): number | null => {
    if (!secPoints.length || secDistanceMap.length === 0) return null;
    if (distance <= 0) return secPoints[0][2];
    if (distance >= secDistanceMap[secDistanceMap.length - 1])
      return secPoints[secPoints.length - 1][2];

    let segmentIndex = 0;
    while (
      segmentIndex < secDistanceMap.length - 1 &&
      distance > secDistanceMap[segmentIndex + 1]
    ) {
      segmentIndex++;
    }
    if (segmentIndex >= secPoints.length - 1) return secPoints[secPoints.length - 1][2];

    const startPoint = secPoints[segmentIndex];
    const endPoint = secPoints[segmentIndex + 1];
    const startDist = secDistanceMap[segmentIndex];
    const endDist = secDistanceMap[segmentIndex + 1];
    const segmentLength = endDist - startDist;
    if (segmentLength <= 0) return startPoint[2];

    const ratio = (distance - startDist) / segmentLength;
    return startPoint[2] + (endPoint[2] - startPoint[2]) * ratio;
  };

  React.useEffect(() => {
    if (!svgRef.current) return;
    if (!polylineRef.current) return;
    if (!cursorLineRef.current) return;
    if (!cursorLineHorizontalRef.current) return;
    if (!cursorTextRef.current) return;
    if (!elevationLinesRef.current) return;
    if (!yAxisLabelsRef.current) return;

    const cursorLine = cursorLineRef.current;
    const cursorLineHorizontal = cursorLineHorizontalRef.current;
    const cursorText = cursorTextRef.current;
    const elevationLines = elevationLinesRef.current;
    const yAxisLabels = yAxisLabelsRef.current;

    if (points.length < 2) return;
    if (!points[0]?.[2]) return;

    // Собираем все высоты для общего масштаба (факт + план)
    const factHeights = points.map((p) => p[2]);
    let allHeights = [...factHeights];
    if (secondaryPoints && secondaryPoints.length) {
      const planHeights = secondaryPoints.map((p) => p[2]);
      allHeights = [...allHeights, ...planHeights];
    }
    const maxOverall = Math.max(...allHeights);
    const minOverall = Math.min(...allHeights);
    const diffOverall = maxOverall - minOverall || 50;

    let totalDistance = 0;
    const pointDistanceMap = [0];
    let totalDuration = 0;
    const pointTimeMap: number[] = [0];

    // Calculate distance and time maps for main points
    for (let i = 1; i < points.length; i++) {
      if (!points[i - 1] || !points[i]) continue;

      // Distance calculation
      const cur = getDistanceBetweenPointsInMeters(points[i - 1], points[i]);
      totalDistance += cur;
      pointDistanceMap[i] = totalDistance;

      // Time calculation
      if (timestamps && timestamps.length === points.length) {
        pointTimeMap[i] = timestamps[i] - timestamps[0];
      } else {
        // Fallback: estimate time based on distance and average speed
        const estimatedTime = totalDistance / 5; // 5 m/s ≈ 18 km/h average speed
        pointTimeMap[i] = estimatedTime * 1000; // Convert to milliseconds
      }
    }

    if (timestamps && timestamps.length === points.length) {
      totalDuration = timestamps[timestamps.length - 1] - timestamps[0];
    } else {
      totalDuration = pointTimeMap[pointTimeMap.length - 1];
    }

    // Построение карты расстояний для secondaryPoints (если есть)
    let secDistanceMap: number[] = [];
    let secTotalDistance = 0;
    if (secondaryPoints && secondaryPoints.length >= 2) {
      secDistanceMap = [0];
      for (let i = 1; i < secondaryPoints.length; i++) {
        const cur = getDistanceBetweenPointsInMeters(secondaryPoints[i - 1], secondaryPoints[i]);
        secTotalDistance += cur;
        secDistanceMap[i] = secTotalDistance;
      }
    }

    const svg = svgRef.current;
    const chartWidth = svg.clientWidth - padding.left - padding.right;
    const chartHeight = svg.clientHeight - padding.top - padding.bottom;

    // Use time-based scaling for x-axis if timestamps are available
    const useTimeScale = timestamps && timestamps.length === points.length;
    const xFactor = useTimeScale ? chartWidth / totalDuration : chartWidth / totalDistance;
    const vFactor = chartHeight / diffOverall;

    // Time-based interval calculation
    let timeInterval = 1000 * 60; // 1 minute default
    if (xFactor < 0.1) timeInterval = 1000 * 60 * 5; // 5 minutes
    if (xFactor < 0.05) timeInterval = 1000 * 60 * 15; // 15 minutes
    if (xFactor < 0.005) timeInterval = 1000 * 60 * 60; // 1 hour

    // Distance-based interval calculation (fallback)
    let distanceInterval = 500;
    if (xFactor < 0.1) distanceInterval = 1000;
    if (xFactor < 0.05) distanceInterval = 10000;
    if (xFactor < 0.005) distanceInterval = 500000;

    // Clear and redraw time/distance markers
    if (!timeGroupRef.current) return;
    timeGroupRef.current.innerHTML = '';

    if (useTimeScale) {
      // Draw time markers
      const totalIntervals = Math.ceil(totalDuration / timeInterval);
      for (let i = 0; i <= totalIntervals; i++) {
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        const x = padding.left + i * timeInterval * xFactor;
        const currentTime = timestamps[0] + i * timeInterval;
        const timeStr = timeFormatter(currentTime);

        line.setAttribute('x1', x.toString());
        line.setAttribute('x2', x.toString());
        line.setAttribute('y1', padding.top.toString());
        line.setAttribute('y2', (svg.clientHeight - padding.bottom).toString());
        line.setAttribute('stroke', 'currentColor');
        line.setAttribute(
          'style',
          i % 5 === 0 ? 'stroke-dasharray: 4; opacity: 0.2' : 'stroke-dasharray: 8; opacity: 0.1',
        );
        timeGroupRef.current.appendChild(line);

        if (i === 0) continue;

        // Add time label for major intervals
        if (i % 5 === 0) {
          const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          text.textContent = timeStr;
          text.setAttribute('x', (x + 3).toString());
          text.setAttribute('y', (svg.clientHeight - 10).toString());
          text.setAttribute('text-anchor', 'start');
          text.setAttribute('style', 'fill: currentColor; opacity: 0.5; font-size: 10px');
          timeGroupRef.current.appendChild(text);
        }
      }
    } else {
      // Draw distance markers (original behavior)
      const totalKms = totalDistance / distanceInterval;
      for (let i = 0; i <= totalKms; i++) {
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        const x = padding.left + i * distanceInterval * xFactor;
        const kmStr = ((i * distanceInterval) / 1000).toString();

        line.setAttribute('x1', x.toString());
        line.setAttribute('x2', x.toString());
        line.setAttribute('y1', padding.top.toString());
        line.setAttribute('y2', (svg.clientHeight - padding.bottom).toString());
        line.setAttribute('stroke', 'currentColor');
        line.setAttribute(
          'style',
          kmStr.includes('.')
            ? 'stroke-dasharray: 8; opacity: 0.1'
            : 'stroke-dasharray: 4; opacity: 0.2',
        );
        timeGroupRef.current.appendChild(line);

        if (i === 0) continue;
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.textContent = `${kmStr}\u2008km`;
        text.setAttribute('x', (x + 3).toString());
        text.setAttribute('y', (svg.clientHeight - 10).toString());
        text.setAttribute('text-anchor', 'start');
        text.setAttribute('style', 'fill: currentColor; opacity: 0.5; font-size: 10px');
        timeGroupRef.current.appendChild(text);
      }
    }

    // Clear and redraw elevation lines and y-axis labels
    elevationLines.innerHTML = '';
    yAxisLabels.innerHTML = '';

    const drawElevationLine = (value: number, color: string, dashArray: string) => {
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      const y = padding.top + (maxOverall - value) * vFactor;

      line.setAttribute('x1', padding.left.toString());
      line.setAttribute('x2', (svg.clientWidth - padding.right).toString());
      line.setAttribute('y1', y.toString());
      line.setAttribute('y2', y.toString());
      line.setAttribute('stroke', color);
      line.setAttribute('stroke-dasharray', dashArray);
      line.setAttribute('stroke-width', '1');
      line.setAttribute('opacity', '0.5');
      elevationLines.appendChild(line);
    };

    // Опорные линии по общей максимальной, средней и минимальной высоте
    const avgOverall = allHeights.reduce((a, b) => a + b, 0) / allHeights.length;
    drawElevationLine(maxOverall, 'red', '4,2');
    drawElevationLine(avgOverall, 'green', '2,2');
    drawElevationLine(minOverall, 'blue', '4,2');

    const drawYAxisLabel = (value: number, text: string, color: string) => {
      const y = padding.top + (maxOverall - value) * vFactor;

      const textEl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      textEl.textContent = text;
      textEl.setAttribute('x', (padding.left - 5).toString());
      textEl.setAttribute('y', y.toString());
      textEl.setAttribute('text-anchor', 'end');
      textEl.setAttribute('dominant-baseline', 'middle');
      textEl.setAttribute('style', `fill: ${color}; font-size: 10px`);
      yAxisLabels.appendChild(textEl);
    };

    drawYAxisLabel(maxOverall, valueFormater(maxOverall), 'red');
    drawYAxisLabel(avgOverall, valueFormater(avgOverall), 'green');
    drawYAxisLabel(minOverall, valueFormater(minOverall), 'blue');

    svg.setAttribute('viewBox', `0 0 ${svg.clientWidth} ${svg.clientHeight}`);
    svg.setAttribute('style', `user-select: none;`);

    const pl = polylineRef.current;
    const pointsIndexXY: [number, number][] = [];
    pl.setAttribute(
      'points',
      points
        .map((e, i) => {
          const xValue = useTimeScale ? pointTimeMap[i] : pointDistanceMap[i];
          const x = padding.left + xValue * xFactor;
          const y = padding.top + (maxOverall - e[2]) * vFactor;
          const xy = [x, y].join(',');
          pointsIndexXY[i] = [x, y];
          return xy;
        })
        .join(' '),
    );

    // Отрисовка вторичной линии (план)
    if (
      secondaryPolylineRef.current &&
      secondaryPoints &&
      secondaryPoints.length >= 2 &&
      secDistanceMap.length
    ) {
      const planPolyline = secondaryPolylineRef.current;
      const pointsStr = points
        .map((_, i) => {
          const distance = pointDistanceMap[i];
          const plannedElev = getPlannedElevationAtDistance(
            distance,
            secondaryPoints,
            secDistanceMap,
          );
          if (plannedElev === null) return null;
          const x = padding.left + (useTimeScale ? pointTimeMap[i] : distance) * xFactor;
          const y = padding.top + (maxOverall - plannedElev) * vFactor;
          return `${x},${y}`;
        })
        .filter(Boolean)
        .join(' ');
      planPolyline.setAttribute('points', pointsStr);
      planPolyline.setAttribute('stroke', secondaryOptions.color || '#ff0000');
      planPolyline.setAttribute('stroke-dasharray', secondaryOptions.strokeDasharray || '5,5');
      planPolyline.setAttribute('stroke-width', String(secondaryOptions.strokeWidth || 2));
      planPolyline.setAttribute('fill', 'none');
      planPolyline.style.display = 'block';
    } else if (secondaryPolylineRef.current) {
      secondaryPolylineRef.current.setAttribute('points', '');
      secondaryPolylineRef.current.style.display = 'none';
    }

    // Draw POI
    if (poiGroupRef.current && poi?.length) {
      poiGroupRef.current.innerHTML = '';
      let lastPoi;
      for (let i = 0; i <= points.length; i++) {
        const point = poi.find(
          (p) =>
            points[i] &&
            p.coordinates &&
            round(p.coordinates[0], 4) === round(points[i][0], 4) &&
            round(p.coordinates[1], 4) === round(points[i][1], 4),
        );

        if (point && point !== lastPoi) {
          lastPoi = point;
          const isBottom = pointsIndexXY[i][1] > svg.clientHeight / 2;

          const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
          line.setAttribute('x1', pointsIndexXY[i][0].toString());
          line.setAttribute('x2', pointsIndexXY[i][0].toString());
          line.setAttribute('y1', (pointsIndexXY[i][1] + (isBottom ? -6 : 6)).toString());
          line.setAttribute('y2', (pointsIndexXY[i][1] + (isBottom ? 3 : -3)).toString());
          line.setAttribute('stroke', point.color ?? 'currentColor');
          !point.is_in_distance && line.setAttribute('style', `stroke-dasharray: 4; opacity: 0.6`);
          poiGroupRef.current.appendChild(line);

          const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          const textPathId = `textPathFor${point.id}${performance.now()}`;
          path.setAttribute('id', textPathId);
          path.setAttribute('fill', 'none');
          path.setAttribute('stroke', 'none');
          path.setAttribute(
            'd',
            isBottom
              ? `M ${pointsIndexXY[i][0]} ${pointsIndexXY[i][1]} L ${pointsIndexXY[i][0]} ${padding.top}`
              : `M ${pointsIndexXY[i][0]} ${pointsIndexXY[i][1]} L ${pointsIndexXY[i][0]} ${svg.clientHeight - padding.bottom}`,
          );
          poiGroupRef.current.appendChild(path);

          const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          const textPath = document.createElementNS('http://www.w3.org/2000/svg', 'textPath');
          textPath.setAttribute('href', `#${textPathId}`);
          textPath.setAttribute('startOffset', `9px`);
          textPath.setAttribute('dominant-baseline', `middle`);
          textPath.textContent = [
            point.name,
            point.coordinates?.[2] && formatAltitude(point.coordinates?.[2]),
          ]
            .filter(Boolean)
            .join('\u2008');
          text.appendChild(textPath);
          text.setAttribute(
            'style',
            `fill: ${point.color ?? 'currentColor'}; ${point.is_in_distance ? '' : 'opacity: 0.5;'} font-size: 10px`,
          );
          poiGroupRef.current.appendChild(text);
        }
      }
    }

    const handleMouseMove = (e: MouseEvent) => {
      const chartX = e.offsetX - padding.left;
      const chartY = e.offsetY - padding.top;

      if (chartX < 0 || chartX > chartWidth || chartY < 0 || chartY > chartHeight) {
        return;
      }

      cursorLine.setAttribute('x1', e.offsetX.toString());
      cursorLine.setAttribute('x2', e.offsetX.toString());
      cursorLine.setAttribute('y1', padding.top.toString());
      cursorLine.setAttribute('y2', (svg.clientHeight - padding.bottom).toString());

      cursorText.setAttribute('x', e.offsetX.toString());
      cursorText.setAttribute('y', (padding.top + 15).toString());
      cursorText.setAttribute('text-anchor', e.offsetX > svg.clientWidth - 100 ? 'end' : 'start');

      const pct = chartX / chartWidth;

      let interpolatedPoint: [number, number, number] | null = null;
      let currentDistance = 0;
      let currentTime = 0;

      if (useTimeScale) {
        currentTime = totalDuration * pct;
        interpolatedPoint = getInterpolatedPointAtTime(currentTime, points, pointTimeMap);
        currentDistance = interpolatedPoint
          ? getInterpolatedPointAtTime(currentTime, points, pointDistanceMap)?.[2] || 0
          : 0;
      } else {
        currentDistance = totalDistance * pct;
        interpolatedPoint = getInterpolatedPointAtDistance(
          currentDistance,
          points,
          pointDistanceMap,
        );
        currentTime = interpolatedPoint
          ? getInterpolatedPointAtDistance(currentDistance, points, pointTimeMap)?.[2] || 0
          : 0;
      }

      const elevation = interpolatedPoint ? interpolatedPoint[2] : 0;

      // Update cursor text with both distance and time information
      cursorText.innerHTML = `
        <tspan x=${e.offsetX} dy="0">${useTimeScale ? timeFormatter(timestamps[0] + currentTime) : formatDistance(currentDistance)}</tspan>
        <tspan x=${e.offsetX} dy="1.2em">${valueFormater(elevation)}</tspan>
        ${
          useTimeScale
            ? `<tspan x=${e.offsetX} dy="1.2em">${formatDuration(currentTime)}</tspan>`
            : `<tspan x=${e.offsetX} dy="1.2em">${formatDuration(currentTime)}</tspan>`
        }
      `;

      if (interpolatedPoint) {
        onCursorMove?.(interpolatedPoint, currentDistance, currentTime, e);
      }

      cursorLineHorizontal.setAttribute('x1', padding.left.toString());
      cursorLineHorizontal.setAttribute('x2', (svg.clientWidth - padding.right).toString());
      const yPos = padding.top + (maxOverall - elevation) * vFactor;
      cursorLineHorizontal.setAttribute('y1', yPos.toString());
      cursorLineHorizontal.setAttribute('y2', yPos.toString());
    };

    const handleMouseEnter = (e: MouseEvent) => {
      cursorLineHorizontal.style.display = 'block';
      cursorLine.style.display = 'block';
      cursorText.style.display = 'block';
      onStartCursorMove?.(e);
    };

    const handleMouseLeave = (e: MouseEvent) => {
      cursorLineHorizontal.style.display = 'none';
      cursorLine.style.display = 'none';
      cursorText.style.display = 'none';
      onEndCursorMove?.(e);
    };

    svg.addEventListener('mouseenter', handleMouseEnter);
    svg.addEventListener('mouseleave', handleMouseLeave);
    svg.addEventListener('mousemove', handleMouseMove);

    return () => {
      svg.removeEventListener('mouseenter', handleMouseEnter);
      svg.removeEventListener('mouseleave', handleMouseLeave);
      svg.removeEventListener('mousemove', handleMouseMove);
    };
  }, [
    points,
    timestamps,
    secondaryPoints,
    secondaryOptions,
    onCursorMove,
    onStartCursorMove,
    onEndCursorMove,
    padding,
    timeFormatter,
    valueFormater,
  ]);

  return (
    <div style={{ minHeight: 200, background: '#f8f8f8' }}>
      <svg
        viewBox="0 0 200 100"
        xmlns="http://www.w3.org/2000/svg"
        width="100%"
        height="200"
        ref={svgRef}
      >
        <polyline points="" fill="none" stroke="currentColor" ref={polylineRef} />
        <polyline points="" fill="none" ref={secondaryPolylineRef} style={{ display: 'none' }} />
        <g ref={elevationLinesRef}></g>
        <g ref={yAxisLabelsRef}></g>
        <line
          id="cursorLine"
          x1="0"
          y1="0"
          x2="0"
          y2="0"
          stroke="#adadad"
          strokeDasharray="1"
          strokeWidth="1"
          ref={cursorLineRef}
          style={{ display: 'none' }}
        />
        <line
          id="cursorLineHorizontal"
          x1="0"
          y1="0"
          x2="0"
          y2="0"
          stroke="#adadad"
          strokeDasharray="1"
          strokeWidth="1"
          ref={cursorLineHorizontalRef}
          style={{ display: 'none' }}
        />
        <text
          x="0"
          y="0"
          id="cursorText"
          fill="currentColor"
          ref={cursorTextRef}
          style={{ display: 'none' }}
        ></text>
        <g ref={timeGroupRef}></g>
        <g ref={poiGroupRef}></g>
      </svg>
    </div>
  );
};

export default ElevationChart;
